const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');
const fresh = () => {
  const repo = new DocumentRepository([
    { id: 'own', tenant: 'a', owner: 'ed', deleted: false, archived: false },
    { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
    { id: 'done', tenant: 'a', owner: 'x', deleted: false, archived: true },
    { id: 'del', tenant: 'a', owner: 'ed', deleted: true, archived: false },
    { id: 'foreign', tenant: 'b', owner: 'ed', deleted: false, archived: false },
  ]);
  return { repo, service: new DocumentService(repo) };
};
const admin = { tenant: 'a', user: 'ad', role: 'admin' };
const editor = { tenant: 'a', user: 'ed', role: 'editor' };
const viewer = { tenant: 'a', user: 'vi', role: 'viewer' };
const unchanged = (fn, re) => {
  const { repo, service } = fresh();
  const before = JSON.stringify(repo.documents);
  assert.throws(() => fn(service), re);
  assert.equal(JSON.stringify(repo.documents), before);
  assert.deepEqual(repo.audit, []);
};
for (const actor of [admin, editor, viewer]) for (const id of ['missing', 'del', 'foreign'])
  unchanged(s => s.archive(actor, id), /^Error: not found$/);
unchanged(s => s.archive(editor, 'other'), /^Error: forbidden$/);
unchanged(s => s.archive(editor, 'done'), /^Error: forbidden$/);
for (const id of ['own', 'other', 'done']) unchanged(s => s.archive(viewer, id), /^Error: forbidden$/);
unchanged(s => s.archive({ tenant: 'a', user: 'z', role: 'owner' }, 'own'), /^Error: forbidden$/);
{ const { repo, service } = fresh();
  service.archive(editor, 'own'); service.archive(editor, 'own');
  assert.equal(repo.documents[0].archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'ed', document: 'own' }]); }
{ const { repo, service } = fresh();
  service.archive(admin, 'other'); service.archive(admin, 'done');
  assert.equal(repo.documents[1].archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'ad', document: 'other' }]);
  assert.equal(repo.documents.filter(d => d.archived).length, 2); }
console.log('authorization checks passed');

